SELECT v.*, vt.name AS vehicle_type_name, d.name AS dept_name, r.name AS route_name, u1.user_name AS driver_name, vs.name AS vehicle_status_name, u2.user_name AS create_name, ps.name AS plan_status_name, ws.work_status_name AS work_status_name, vlt.violation_name AS violation_type_name, vsts.violation_status_name AS violation_status_name, mt.maintenance_name AS maintenance_type_name, tt.name AS task_type_name FROM sys_vehicle v LEFT JOIN sys_vehicle_type vt ON v.vehicle_type_id = vt.sys_vehicle_type_id AND vt.deleted = 0 LEFT JOIN sys_dept d ON v.dept_id = d.sys_dept_id AND d.deleted = 0 LEFT JOIN sys_route r ON v.route_id = r.sys_route_id AND r.deleted = 0 LEFT JOIN sys_user u1 ON v.driver_id = u1.user_id AND u1.deleted = 0 LEFT JOIN sys_vehicle_status vs ON v.vehicle_status_id = vs.sys_vehicle_status_id AND vs.deleted = 0 LEFT JOIN sys_user u2 ON v.create_by = u2.user_id AND u2.deleted = 0 LEFT JOIN sys_plan_status ps ON v.plan_status_id = ps.sys_plan_status_id AND ps.deleted = 0 LEFT JOIN sys_work_status ws ON v.work_status_id = ws.work_status_id AND ws.deleted = 0 LEFT JOIN sys_violation_type vlt ON v.violation_type_id = vlt.violation_type_id AND vlt.deleted = 0 LEFT JOIN sys_violation_status vsts ON v.violation_status_id = vsts.violation_status_id AND vsts.deleted = 0 LEFT JOIN sys_maintenance_type mt ON v.maintenance_type_id = mt.maintenance_type_id AND mt.deleted = 0 LEFT JOIN sys_task_type tt ON v.task_type_id = tt.sys_task_type_id AND tt.deleted = 0 WHERE v.deleted = 0
AND v.sys_vehicle_id = #{reqVO.sysVehicleId}
AND v.license_plate LIKE CONCAT('%', #{reqVO.licensePlate}, '%')
AND v.vehicle_type_id = #{reqVO.vehicleTypeId}
AND v.model LIKE CONCAT('%', #{reqVO.model}, '%')
AND v.dept_id = #{reqVO.deptId}
AND v.route_id = #{reqVO.routeId}
AND v.maintenance_cycle = #{reqVO.maintenanceCycle}
AND v.driver_id = #{reqVO.driverId}
AND v.vehicle_status_id = #{reqVO.vehicleStatusId}
AND v.create_by = #{reqVO.createBy}
AND v.total_work_hours = #{reqVO.totalWorkHours}
AND v.alarm_count = #{reqVO.alarmCount}
AND v.vehicle_photo_url LIKE CONCAT('%', #{reqVO.vehiclePhotoUrl}, '%')
ORDER BY v.id DESC LIMIT #{reqVO.offset}, #{reqVO.pageSize}

SELECT COUNT(*)
FROM sys_vehicle v
WHERE v.deleted = 0


    AND v.sys_vehicle_id = #{reqVO.sysVehicleId}


    AND v.license_plate LIKE CONCAT('%', #{reqVO.licensePlate}, '%')


